import{_ as A,C as n,o as t,c as i,a7 as a,b as o,w as r,a as h,E as s,a8 as d}from"./chunks/framework.BCbKzsgW.js";const P=JSON.parse('{"title":"多因素认证与 Passkey","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/mfa-passkey.md","filePath":"development/common/authentication/mfa-passkey.md","lastUpdated":1793703140000}'),l={name:"development/common/authentication/mfa-passkey.md"};function p(u,e,c,B,f,b){const E=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="duo-yin-su-ren-zheng-yu-passkey" tabindex="-1">多因素认证与 Passkey <a class="header-anchor" href="#duo-yin-su-ren-zheng-yu-passkey" aria-label="Permalink to &quot;多因素认证与 Passkey&quot;">​</a></h1><p>多因素认证（MFA）要求结合不同类型的身份证明。密码加另一个密码仍是同类因素；“无密码”也不自动代表满足某项多因素保证要求，需要看认证器如何保护私钥、是否执行用户验证，以及恢复流程。</p><p><a href="https://cheatsheetseries.owasp.org/cheatsheets/Multifactor_Authentication_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP MFA</a>区分知识、持有、生物特征等因素，并讨论认证器更换与恢复风险。认证流程的强度也受最弱恢复入口限制。</p><h2 id="ren-zheng-fang-shi-de-shi-ji-chai-bie" tabindex="-1">认证方式的实际差别 <a class="header-anchor" href="#ren-zheng-fang-shi-de-shi-ji-chai-bie" aria-label="Permalink to &quot;认证方式的实际差别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>服务端验证什么</th><th>主要边界</th></tr></thead><tbody><tr><td>短信或邮箱码</td><td>对消息通道的当前控制</td><td>通道失陷、转发、换卡与账号恢复</td></tr><tr><td>TOTP</td><td>对共享种子的控制</td><td>可被实时钓鱼，服务端需保护种子</td></tr><tr><td>推送确认</td><td>对已注册设备的控制与确认</td><td>疲劳轰炸、误确认与设备失陷</td></tr><tr><td>WebAuthn / Passkey</td><td>面向指定 RP 的私钥签名</td><td>认证器能力、用户验证、设备与同步恢复</td></tr><tr><td>一次性恢复码</td><td>对备用秘密的控制</td><td>保存位置与遗失后的处理</td></tr></tbody></table><p>并非所有场景都需要强制同一种方式。管理员和高价值操作应采用更强策略，普通用户的登录成功率、无障碍和恢复成本也需要实际评估。</p><h2 id="totp-zhu-ce-yu-yan-zheng" tabindex="-1">TOTP 注册与验证 <a class="header-anchor" href="#totp-zhu-ce-yu-yan-zheng" aria-label="Permalink to &quot;TOTP 注册与验证&quot;">​</a></h2><p><a href="https://www.rfc-editor.org/rfc/rfc6238.html" target="_blank" rel="noreferrer">RFC 6238</a>使用时间步长驱动 HOTP，服务端和认证器根据共享种子计算短期验证码。常见时间步长为 30 秒；允许的时钟偏差窗口越大，同时可接受的验证码也越多。</p><p>注册建议采用“待确认 → 验证通过 → 启用”的状态：</p><ol><li>用户完成近期认证，服务端生成随机种子，创建短期绑定请求。</li><li>通过受保护页面展示二维码，用户导入认证器。</li><li>用户输入一次有效码，服务端验证后才启用认证器。</li><li>提供恢复码，并记录安全事件与通知。</li></ol><p>TOTP 种子不是普通密码哈希。服务端需要它来计算验证码，因此要加密保存、控制解密权限并规划密钥轮换；二维码、种子和 <code>otpauth</code> URI 不进入日志或分析系统。</p><p>验证时限制账号与挑战的尝试次数，原子记录已接受的时间步，拒绝同一 OTP 在有效窗口内再次成功。跨节点要共享重放状态；容忍时钟漂移不等于允许重复消费。种子重新绑定后，旧种子与旧恢复请求需要失效。</p><h2 id="mfa-tiao-zhan-bu-shi-wan-zheng-deng-lu-tai" tabindex="-1">MFA 挑战不是完整登录态 <a class="header-anchor" href="#mfa-tiao-zhan-bu-shi-wan-zheng-deng-lu-tai" aria-label="Permalink to &quot;MFA 挑战不是完整登录态&quot;">​</a></h2><p>密码正确、MFA 未完成时，只建立短期预认证上下文。该上下文绑定账号、已通过方式、挑战与时限，只能访问完成认证或取消流程所需的端点，不能访问普通业务 API。</p><p>挑战完成后轮换到正式 Session。否则攻击者拿到只验证了密码的 Cookie，就可能绕过第二因素直接调用 API。</p><p>同样，敏感操作的 step-up（提升认证强度）应有短有效期，并绑定到当前会话；高风险动作还可以绑定目标、金额或一次性操作请求。前端自己提交 <code>mfa_passed=true</code> 不产生可信认证事实。</p><h2 id="webauthn-de-zhu-ce-yu-ren-zheng" tabindex="-1">WebAuthn 的注册与认证 <a class="header-anchor" href="#webauthn-de-zhu-ce-yu-ren-zheng" aria-label="Permalink to &quot;WebAuthn 的注册与认证&quot;">​</a></h2><p><a href="https://www.w3.org/TR/webauthn-2/#sctn-rp-operations" target="_blank" rel="noreferrer">W3C WebAuthn Level 2</a>定义注册和认证验证流程。核心关系是：认证器保存私钥，RP 保存公钥与凭据 ID；认证器对含服务端挑战的结果签名，浏览器参与来源与 RP 范围约束。</p><p>服务端使用成熟库完成完整校验，至少明确以下边界：</p><table tabindex="0"><thead><tr><th>阶段</th><th>需要约束的内容</th></tr></thead><tbody><tr><td>发起注册</td><td>当前账号与近期认证、RP ID、允许算法、随机挑战</td></tr><tr><td>完成注册</td><td>挑战、操作类型、受信 origin、RP ID、用户在场及所需用户验证</td></tr><tr><td>发起认证</td><td>账号或可发现凭据策略、一次性挑战与时限</td></tr><tr><td>完成认证</td><td>凭据归属、签名、挑战、origin、RP ID 与标志位</td></tr></tbody></table><p>challenge 需要一次性消费，并绑定发起流程；不能只检查“签名正确”。对允许 origin 使用精确配置，不能随意信任请求的 <code>Host</code>；RP ID 的选择会影响域名范围和未来迁移成本。</p><p>下面展示已登记凭据的认证过程。认证器完成本地交互，服务端负责验证结果并原子消费挑战，两者职责不同。</p>',22)),(t(),o(d,null,{default:r(()=>[s(E,{id:"mermaid-197",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20C%20as%20%E6%B5%8F%E8%A7%88%E5%99%A8%0A%20%20%20%20participant%20A%20as%20%E5%BA%94%E7%94%A8%E6%9C%8D%E5%8A%A1%0A%20%20%20%20participant%20K%20as%20%E8%AE%A4%E8%AF%81%E5%99%A8%0A%20%20%20%20C-%3E%3EA%3A%20%E8%AF%B7%E6%B1%82%20Passkey%20%E8%AE%A4%E8%AF%81%0A%20%20%20%20A-%3E%3EA%3A%20%E5%88%9B%E5%BB%BA%E5%B9%B6%E7%BB%91%E5%AE%9A%E4%B8%80%E6%AC%A1%E6%80%A7%20challenge%0A%20%20%20%20A--%3E%3EC%3A%20challenge%E3%80%81RP%20ID%20%E4%B8%8E%E9%AA%8C%E8%AF%81%E7%AD%96%E7%95%A5%0A%20%20%20%20C-%3E%3EK%3A%20%E8%AF%B7%E6%B1%82%E5%87%AD%E6%8D%AE%E6%96%AD%E8%A8%80%0A%20%20%20%20K-%3E%3EK%3A%20%E7%94%A8%E6%88%B7%E5%9C%A8%E5%9C%BA%E4%B8%8E%E6%89%80%E9%9C%80%E7%94%A8%E6%88%B7%E9%AA%8C%E8%AF%81%0A%20%20%20%20K--%3E%3EC%3A%20%E5%87%AD%E6%8D%AE%20ID%E3%80%81%E7%AD%BE%E5%90%8D%E4%B8%8E%E8%AE%A4%E8%AF%81%E6%95%B0%E6%8D%AE%0A%20%20%20%20C-%3E%3EA%3A%20%E6%8F%90%E4%BA%A4%E6%96%AD%E8%A8%80%E4%B8%8E%E5%AE%A2%E6%88%B7%E7%AB%AF%E6%95%B0%E6%8D%AE%0A%20%20%20%20A-%3E%3EA%3A%20%E6%A0%A1%E9%AA%8C%E6%9D%A5%E6%BA%90%E3%80%81RP%20ID%E3%80%81%E5%BD%92%E5%B1%9E%E5%8F%8A%E7%AD%BE%E5%90%8D%0A%20%20%20%20A-%3E%3EA%3A%20%E6%A3%80%E6%9F%A5%E6%A0%87%E5%BF%97%E4%B8%8E%E6%8C%91%E6%88%98%EF%BC%8C%E5%8E%9F%E5%AD%90%E6%B6%88%E8%B4%B9%0A%20%20%20%20alt%20%E6%A0%A1%E9%AA%8C%E5%A4%B1%E8%B4%A5%E3%80%81%E8%BF%87%E6%9C%9F%E6%88%96%E5%B7%B2%E6%B6%88%E8%B4%B9%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%8B%92%E7%BB%9D%E8%AE%A4%E8%AF%81%0A%20%20%20%20else%20%E5%85%A8%E9%83%A8%E9%AA%8C%E8%AF%81%E9%80%9A%E8%BF%87%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E5%BB%BA%E7%AB%8B%E4%BC%9A%E8%AF%9D%E6%88%96%E5%AE%8C%E6%88%90%E6%9C%AC%E6%AC%A1%E5%BC%BA%E8%AE%A4%E8%AF%81%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>图中省略用户取消和设备不可用的分支：它们结束此次尝试，不生成成功认证结果。所需用户验证失败时也不能降级跳过；备用方式遵循已有账号策略。</p><h2 id="passkey-yu-yong-hu-yan-zheng" tabindex="-1">Passkey 与用户验证 <a class="header-anchor" href="#passkey-yu-yong-hu-yan-zheng" aria-label="Permalink to &quot;Passkey 与用户验证&quot;">​</a></h2><p><a href="https://fidoalliance.org/passkeys/" target="_blank" rel="noreferrer">FIDO Alliance 的 Passkey 说明</a>将其建立在 FIDO 公钥认证之上。Passkey 可以有设备绑定或可同步的形态，不能笼统承诺私钥永远不会离开当前设备。</p><p>用户可能通过本地 PIN 或生物识别解锁认证器。服务端通常收到签名及用户验证结果，不接收指纹或人脸模板。业务若要求用户验证，需要在请求中明确策略并在响应中校验结果；仅发生用户触碰不等于已完成同等强度验证。</p><p>WebAuthn 的 RP 绑定能抵御典型仿冒域名钓鱼，但不能消除本站 XSS、恶意扩展、已解锁设备失陷或账号恢复入口风险。是否满足特定认证保证等级，还要评估认证器与部署条件，不能只看“支持 Passkey”字样。</p><p>同步凭据的签名计数可能不具备严格单调特征。计数异常应结合认证器能力与风险策略处理，不适合一律永久封号。设备证明（attestation）也不是普通网站必选项；强制特定硬件会增加隐私、兼容性和供应链约束。</p><h2 id="ren-zheng-qi-guan-li-yu-hui-fu" tabindex="-1">认证器管理与恢复 <a class="header-anchor" href="#ren-zheng-qi-guan-li-yu-hui-fu" aria-label="Permalink to &quot;认证器管理与恢复&quot;">​</a></h2><p>用户应能登记多个独立认证器，查看创建时间和最近使用情况，并撤销丢失设备。添加、删除或替换认证器要视作敏感操作，不能仅凭一个长期登录 Cookie 完成。</p><p>恢复码使用足够随机的独立秘密，只展示给用户并保存摘要，单次原子消费。重新生成一组后使旧组整体失效，避免遗漏的旧纸条继续具有账号控制权。</p><p>恢复流程需要明确：所有认证器丢失时接受什么证据、是否有等待期、如何通知已有渠道、恢复后撤销哪些会话。移除 MFA 后若仍保留攻击者已有会话，用户即使恢复成功也没有夺回全部控制权。</p><p>对必须强认证的账号，不应在认证器服务不可用时自动跳过 MFA。可以提供预先登记的备用方式或受审计的恢复流程，不能临时生成一个无审查的绕过接口。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>OWASP：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Multifactor_Authentication_Cheat_Sheet.html" target="_blank" rel="noreferrer">Multifactor Authentication Cheat Sheet</a></li><li>IETF：<a href="https://www.rfc-editor.org/rfc/rfc6238.html" target="_blank" rel="noreferrer">RFC 6238 — TOTP</a></li><li>W3C：<a href="https://www.w3.org/TR/webauthn-2/#sctn-rp-operations" target="_blank" rel="noreferrer">WebAuthn Level 2 — Relying Party Operations</a></li><li>FIDO Alliance：<a href="https://fidoalliance.org/passkeys/" target="_blank" rel="noreferrer">Passkeys</a></li></ul>',13))])}const m=A(l,[["render",p]]);export{P as __pageData,m as default};
